/*
 * AlkalineVoice.c - the Alkaline (TB-303) voice engine (S093 P0, P3).
 * See AlkalineVoice.h. Behaviour: S092_P6_DSP_EQUATIONS.md §4.6 and the
 * validated pattern driver tools/alkaline/validate.py dsp_pattern().
 */
#include <math.h>







/* slide lag: tau = 100 k x 0.22 uF = 22 ms (S092 P0 A9); kept per block */
#define ALK_SLIDE_KEEP   0.967561f      /* e^(-0.7255 ms / 22 ms) */
/* VCO -> volts at S1 (S092 P6 §3.6): sawTable ramps +-32,625 LSB for the
 * 303 saw's 5.35 V; the square table carries ALK_SQR_SCALE_V. */
#define ALK_SAW_SCALE_V  (2.675f / 32625.0f)
#define ALK_V561         3.263f

void Alkaline_initVoice(AlkalineVoice *voice)
{
	if (!voice)
		return;
	voice->osc.waveform = SAW;
	voice->osc.freq = 65.406f;
	voice->osc.pitchMod = 1.0f;
	voice->osc.modNodeValue = 1.0f;
	voice->osc.midiFreq = (uint16_t)((36u << 8) | 63u);   /* coa 36 = C2; fine at its centre */
	voice->osc.baseNote = MIDI_DEFAULT_TRIGGER_NOTE;
	DiodeLadder_init(&voice->ladder);
	alkMeg_init(&voice->meg);
	alkAcc_init(&voice->accNet);
	alkVeg_init(&voice->veg);
	lfo_init(&voice->lfo);

	/* S093 P4: the bytes of SD_CARD/Instrument/Alkaline/init.alk, as TYPE_FLT
	 * stores them (byte / 127), so a voice before its first apply and a
	 * freshly loaded init.alk are the same sound: the five 303 knobs at 64
	 * (the nearest byte to half rotation), Tuning at its centre 63, drive 0
	 * (x1), vol 100 */
	voice->cutoff = 64.0f / 127.0f;
	voice->reso = 64.0f / 127.0f;
	voice->envMod = 64.0f / 127.0f;
	voice->decay = 64.0f / 127.0f;
	voice->accent = 64.0f / 127.0f;
	voice->tuning = 63.0f / 127.0f;
	voice->drive = 0.0f;
	voice->attack = 0.0f;   /* S093 P6: init.alk alk_attack = 0, today's attack */
	voice->vol = 100.0f / 127.0f;
	voice->pan = 63u;
	voice->wave = ALK_WAVE_SAW;
	voice->slide = 0u;

	voice->note = MIDI_DEFAULT_TRIGGER_NOTE;
	voice->slideLatch = 0u;
	voice->gliding = 0u;
	voice->accentOn = 0u;
	voice->pitchJump = 1u;
	voice->gateLeft = 0;
	voice->accentLeft = 0;
	voice->pitchLog2 = alk_log2f(65.406f);
	voice->v134 = ALK_V561;
	voice->iLadRaw = 7.375e-6f;   /* the expo warm start (T1-4): the calibration current */
	voice->iLadEnd = 0.0f;
	voice->iAbcEnd = 0.0f;
	voice->driveGain = 1.0f;
	voice->makeup = alk_exp2f(ALK_MAKEUP_OCT);
}

/*
 * S092 P0 §5.3 / §5.4: accent from velocity; legato when the previous note
 * was slide-flagged and its gate is still held; the slide flag is latched
 * for the next trigger; the gate is 7/12 of a step, or the whole step plus
 * the next step's gate after a slide-flagged note. S093 P4: the platform
 * part first, as Drum_triggerVoice(). Contract: AlkalineVoice.h.
 */
void Alkaline_triggerVoice(AlkalineVoice *voice, const uint8_t source_slot,
                           const uint8_t velocity, const uint8_t note,
                           const uint32_t stepSamples)
{
	/* the velocity as the modulation system's 0..1 value (Drum: vol/127.f) */
	const float vel = (float)velocity * (1.0f / 127.0f);
	/* the normal gate: 7/12 of the step (3.5 of 6 clocks, D11), rounded to
	 * the nearest sample; counted down by 32 per block, so it stays open for
	 * every block that starts before its end (S093 P0 §5.3) */
	const int32_t gate = (int32_t)((stepSamples * ALK_GATE_NUM + ALK_GATE_DEN / 2u)
	                               / ALK_GATE_DEN);
	/* legato: the previous note asked to slide (latched at its trigger) and
	 * its gate is still open; a slide into a rest closes the gate first */
	const uint8_t legato = 0u;

	/* --- platform part (S093 P4): LFO and velocity, per slot --- */
	/* restart the slot's LFO phase when its rtg mode asks for it */
	lfo_retrigger(source_slot);
	/* the velocity node drives direct descriptor targets (velo_mod_dest) */
	modNode_updateValue(&velocityModulators[source_slot], vel);
	/* targets that are not direct nodes (slot decimation, Scene targets):
	 * InstrumentManager applies or ignores them; it stays beside the node
	 * update so no trigger client needs to know which kind is installed */
	instrumentManager_applyVelocityModulationTarget(source_slot, vel);

	/* --- the 303 rules (unchanged from S093 P0) --- */
	voice->note = note;
	/* D1: velocity 101+ is an accent; the default step velocity 100 is not */
	voice->accentOn = (uint8_t)(velocity >= ALK_ACCENT_VELOCITY);
	/* the ACCENT lane is high for one step (S092 P4 E3) */
	voice->accentLeft = (int32_t)stepSamples;
	voice->gliding = legato;
	if (!legato) {
		/* a new note: jump the pitch, strike the MEG, trigger the VEG */
		voice->pitchJump = 1u;
		alkMeg_trigger(&voice->meg);
		alkVeg_trigger(&voice->veg, voice->attack);
		/*
		 * S093 P6: pos, the note-start phase (user).
		 *
		 * What:       pos 0 leaves the oscillator free-running (the 303's VCO,
		 *             today's sound bit for bit); pos 1..127 sets the phase to
		 *             pos/128 of a cycle at every non-legato note, so each
		 *             note starts at the same point of the waveform (a
		 *             zero-crossing start and a peak start give a different
		 *             onset into the ladder). positionApplied re-anchors to
		 *             pos either way, so no bend follows the trigger.
		 * Why:        a phase offset on a free-running oscillator is not heard
		 *             (S093 P6 plan §8.1); the reset gives pos a sound.
		 * Inputs:     osc.position (osc1_position, 0..127).
		 * Outputs:    osc.phase (pos != 0), osc.positionApplied.
		 * Affiliates: the per-block bend in Alkaline_calcVoiceAsync(); the
		 *             fused loop's 32-bit cycle (DiodeLadder.c: index ph >> 22
		 *             of 1024), so pos << 25 is pos/128 of it.
		 */
		{
			const uint8_t pos = (uint8_t)(voice->osc.position & 127u);

			if (pos != 0u)
				voice->osc.phase = (uint32_t)pos << 25;
			voice->osc.positionApplied = pos;
		}
	}
	/* this note's slide flag decides the next trigger (A10) */
	voice->slideLatch = (uint8_t)(voice->slide != 0u);
	/* a slide-flagged note holds its gate through the next step's gate */
	voice->gateLeft = voice->slideLatch ? (int32_t)stepSamples + gate : gate;
}

void Alkaline_calcVoiceAsync(AlkalineVoice *voice)
{
	const uint8_t gateOn = (uint8_t)(voice->gateLeft > 0);
	float n53, vW4, iAcc, dv, iLad, target, k, f;
	uint8_t lo;

	/* the lanes are high for every block that starts before their end */
	if (voice->accentLeft <= 0)
		voice->accentOn = 0u;
	voice->gateLeft = (voice->gateLeft > OUTPUT_DMA_SIZE) ? voice->gateLeft - OUTPUT_DMA_SIZE : 0;
	voice->accentLeft = (voice->accentLeft > OUTPUT_DMA_SIZE) ? voice->accentLeft - OUTPUT_DMA_SIZE : 0;

	/* pitch: coarse + note + fine from the oscillator, slide lag in log2 Hz,
	 * Tuning +-700 cents; fast log2/exp2 (T1-6) and the direct table-wave
	 * setup (T1-7: osc_setFreq()'s cache misses every block of a glide) */
	/* S093 P3: log2 of osc_setBaseNote()'s frequency straight from the note
	 * (MidiNoteFrequencies is equal-tempered to 1e-4 cent) and the fine byte
	 * (midiPitch_detune() is 1 + x, |x| <= 0.03: log2 by its second order,
	 * within 5e-6); osc.baseNote is kept for the coarse writer's
	 * osc_recalcFreq() */
	{
		int16_t n = (int16_t)(voice->osc.midiFreq >> 8) + (int16_t)voice->note
		          - (int16_t)MIDI_DEFAULT_TRIGGER_NOTE;
		const float x = midiPitch_detune((uint8_t)(voice->osc.midiFreq & 0xffu)) - 1.0f;

		n = (n < 0) ? 0 : ((n > 127) ? 127 : n);
		voice->osc.baseNote = voice->note;
		target = 8.78135971f + ((float)n - 69.0f) * (1.0f / 12.0f)   /* log2(440) */
		       + x * (ALK_LOG2E - 0.5f * ALK_LOG2E * x);
	}
	if (voice->pitchJump || !voice->gliding)
		voice->pitchLog2 = target;
	else
		voice->pitchLog2 = target + (voice->pitchLog2 - target) * ALK_SLIDE_KEEP;
	voice->pitchJump = 0u;
	voice->osc.freq = alk_exp2f(voice->pitchLog2
	                        + (voice->tuning * 127.0f - 63.0f) * (7.0f / 12.0f / 63.0f));
	osc_setTableFreq(&voice->osc);
	/*
	 * S093 P6: pos while it moves: the per-block bend (the stock waves' rule,
	 * Oscillator.h osc_positionBendApply(), INSTRUMENTS_DSP_REFERENCE §6.1.1).
	 *
	 * What:       d = the circular step from the applied position to pos,
	 *             -64..+63 (127 -> 0 is +1); positionApplied advances by d and
	 *             phaseInc gains d x OSC_POS_BEND_PER_STEP (2^25 / 32), which
	 *             held for the 32-sample block moves the phase by exactly d/128
	 *             of a cycle: the oscillator lands on the new offset, no drift.
	 * Why:        a pos change at a block edge would click; the bend spreads it
	 *             over the block as a small pitch excursion. The stock helper
	 *             is not used: it requires osc_positionBendRestore() after the
	 *             render, and Alkaline recomputes phaseInc every block
	 *             (osc_setTableFreq() above), so the bend clears itself. That is
	 *             S3 of the plan (§7.3), a saving shared with P7.
	 * Cost:       13 instructions per block (+0.41 per sample; the block
	 *             compiled alone for the M7 at -Ofast). The plan's +0.8
	 *             counted the stock apply/restore pair; the linked count
	 *             (control_cost.py) decides.
	 *             No cap: |d| <= 64 = OSC_POS_BEND_CAP.
	 * Constant:   at a steady pos d = 0 and phaseInc is unchanged (pos 0:
	 *             today's oscillator bit for bit).
	 */
	{
		const uint32_t u = ((uint32_t)(voice->osc.position & 127u) -
		                    (uint32_t)voice->osc.positionApplied + 64u) & 127u;
		const int32_t d = (int32_t)u - 64;

		voice->osc.positionApplied =
			(uint8_t)(((uint32_t)voice->osc.positionApplied + (uint32_t)d) & 127u);
		voice->osc.phaseInc += (uint32_t)(d * (int32_t)OSC_POS_BEND_PER_STEP);
	}

	/* control path (S092 P6 §4) */
	n53 = alkMeg_step(&voice->meg, voice->decay, voice->accentOn);
	/* S093 P6: the accent sweep's VR4b gang stays on the 303's pot: the
	 * knob's physical rotation is min(k_eff, 1), k_eff = ALK_RES_KMAX x knob
	 * (above 1 only VR4a's virtual wiper stage grows) */
	alkAcc_step(&voice->accNet, voice->accentOn, voice->accent,
	            fminf(ALK_RES_KMAX * voice->reso, 1.0f),
	            n53, voice->v134, &vW4, &iAcc);
	iLad = alk_expoCurrent(voice->cutoff, voice->envMod, n53, vW4, voice->iLadRaw, &dv);
	voice->v134 = ALK_V561 + dv;
	voice->iAbcEnd = alkVeg_step(&voice->veg, gateOn) + iAcc;
	voice->iLadRaw = iLad;
	voice->iLadEnd = iLad * alk_prewarp(iLad, voice->reso);

	/* drive x1..x16 (S093 P6, user: twice the former x8 maximum; D16) and the
	 * output make-up falling with it (B-2) */
	{
		const float drv = fminf(fmaxf(voice->drive, 0.0f), 1.0f);

		const float t = alk_exp2f(drv);                             /* T1-8 */
		const float t2 = t * t;

		/* 16^drv = (2^drv)^4: x1 at 0, x4 at the middle, x16 at 1 */
		voice->driveGain = t2 * t2;
		voice->makeup = alk_exp2f(ALK_MAKEUP_OCT * (1.0f - drv));
	}

	/* Res-interpolated network for this block */
	k = fminf(fmaxf(voice->reso, 0.0f), 1.0f) * (float)(ALK_RES_POINTS - 1u);
	lo = (uint8_t)k;
	if (lo > ALK_RES_POINTS - 2u)
		lo = (uint8_t)(ALK_RES_POINTS - 2u);
	f = k - (float)lo;
	DiodeLadder_setNet(&voice->ladder, &alkResTable[lo], &alkResTable[lo + 1u], f);
}

void Alkaline_calcVoiceSyncBlock(AlkalineVoice *voice, int16_t *buf, const uint8_t size)
{
	const uint8_t square = (uint8_t)(voice->wave == ALK_WAVE_SQUARE);

	(void)size;   /* the ladder always renders OUTPUT_DMA_SIZE */
	/* B2R (user, S093). The make-up scales the OTA current, which the kernel
	 * already ramps per sample and which feeds only the output, so the
	 * per-sample loop is the same with or without it. */
#if ALK_FUSED_OSC
	/* S093 P3: the oscillator's table read fused into the B2R loop (-9 per
	 * sample, bit-identical: bench law AL-X). Only for the [11][1024] table
	 * waves; another oscillator type would take the separate path below. */
	DiodeLadder_renderB2Osc(&voice->ladder, buf,
	                        square ? alkSqrTable[voice->osc.tableOffset]
	                               : sawTable[voice->osc.tableOffset],
	                        &voice->osc.phase, voice->osc.phaseInc,
	                        (square ? ALK_SQR_SCALE_V : ALK_SAW_SCALE_V) * voice->driveGain,
	                        voice->iLadEnd, voice->iAbcEnd * voice->makeup);
#else
	calcWavetableOscBlock(&voice->osc, square ? alkSqrTable : sawTable, buf,
	                      OUTPUT_DMA_SIZE, 1.0f);
	DiodeLadder_renderB2(&voice->ladder, buf,
	                     (square ? ALK_SQR_SCALE_V : ALK_SAW_SCALE_V) * voice->driveGain,
	                     voice->iLadEnd, voice->iAbcEnd * voice->makeup);
#endif
}

uint8_t Alkaline_isQuiet(const AlkalineVoice *voice)
{
	return (uint8_t)(voice->gateLeft == 0 && !voice->accentOn &&
	                 voice->iAbcEnd < 1e-7f);
}

